CREATE TYPE "BookingStatus" AS ENUM ('pending_payment', 'confirmed', 'cancelled', 'expired');
CREATE TYPE "PaymentStatus" AS ENUM ('created', 'paid', 'failed', 'refunded');
CREATE TABLE "vendors" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "password_hash" TEXT NOT NULL, "business_name" TEXT NOT NULL, "public_slug" TEXT NOT NULL UNIQUE, "advance_amount_paise" INTEGER NOT NULL CHECK ("advance_amount_paise" > 0), "total_amount_paise" INTEGER NOT NULL CHECK ("total_amount_paise" >= "advance_amount_paise"), "terms" TEXT NOT NULL DEFAULT '', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "bookings" ("id" TEXT PRIMARY KEY, "vendor_id" TEXT NOT NULL REFERENCES "vendors"("id") ON DELETE RESTRICT, "client_name" TEXT NOT NULL, "client_email" TEXT NOT NULL, "event_date" DATE NOT NULL, "status" "BookingStatus" NOT NULL DEFAULT 'pending_payment', "advance_amount_paise" INTEGER NOT NULL, "total_amount_paise" INTEGER NOT NULL, "contract_accepted_at" TIMESTAMP(3), "expires_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "payments" ("id" TEXT PRIMARY KEY, "booking_id" TEXT NOT NULL UNIQUE REFERENCES "bookings"("id") ON DELETE RESTRICT, "razorpay_order_id" TEXT NOT NULL UNIQUE, "razorpay_payment_id" TEXT UNIQUE, "amount_paise" INTEGER NOT NULL, "status" "PaymentStatus" NOT NULL DEFAULT 'created', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "refresh_tokens" ("id" TEXT PRIMARY KEY, "vendor_id" TEXT NOT NULL REFERENCES "vendors"("id") ON DELETE CASCADE, "token_hash" TEXT NOT NULL UNIQUE, "expires_at" TIMESTAMP(3) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "bookings_vendor_id_event_date_idx" ON "bookings"("vendor_id", "event_date");
-- This is the final authority under concurrent requests and across server instances.
CREATE UNIQUE INDEX "one_confirmed_booking_per_vendor_date" ON "bookings"("vendor_id", "event_date") WHERE "status" = 'confirmed';
